1	package parcelrate
2	
3	import (
4		"fmt"
5		"strconv"
6		"strings"
7	)
8	
9	// Service is a delivery speed.
10	type Service int
11	
12	const (
13		Standard Service = iota
14		Express
15	)
16	
17	func (s Service) String() string {
18		switch s {
19		case Standard:
20			return "Standard"
21		case Express:
22			return "Express"
23		}
24		return "Service(" + strconv.Itoa(int(s)) + ")"
25	}
26	
27	// Tier is one row of a weight price list: parcels weighing up to and
28	// including UpToGrams cost Cents (zone 1 price, before surcharges).
29	type Tier struct {
30		UpToGrams int
31		Cents     int64
32	}
33	
34	var standardTiers = []Tier{
35		{UpToGrams: 500, Cents: 420},
36		{UpToGrams: 1000, Cents: 560},
37		{UpToGrams: 2000, Cents: 790},
38		{UpToGrams: 5000, Cents: 1250},
39		{UpToGrams: 10000, Cents: 1980},
40		{UpToGrams: 20000, Cents: 2950},
41	}
42	
43	// TODO(2021): express prices should come from the carrier API like the fuel surcharge.
44	var expressTiers = []Tier{
45		{UpToGrams: 500, Cents: 890},
46		{UpToGrams: 1000, Cents: 1090},
47		{UpToGrams: 2000, Cents: 1390},
48		{UpToGrams: 5000, Cents: 1990},
49		{UpToGrams: 10000, Cents: 2890},
50		{UpToGrams: 20000, Cents: 3990},
51	}
52	
53	// Charge is one line of a quotation.
54	type Charge struct {
55		Name  string
56		Cents int64
57	}
58	
59	// Quotation is the price of sending one parcel with one service.
60	type Quotation struct {
61		Service    Service
62		Zone       Zone
63		Grams      int // billable weight
64		Charges    []Charge
65		TotalCents int64
66	}
67	
68	// Quote prices a parcel sent from one postcode to another with the given service.
69	func Quote(p Parcel, fromPostcode, toPostcode string, svc Service) (Quotation, error) {
70		if err := p.Validate(); err != nil {
71			return Quotation{}, err
72		}
73		var tiers []Tier
74		if svc == Standard {
75			tiers = standardTiers
76		} else if svc == Express {
77			tiers = expressTiers
78		} else {
79			return Quotation{}, fmt.Errorf("parcelrate: unknown service %v", svc)
80		}
81	
82		zone, err := ZoneBetween(fromPostcode, toPostcode)
83		if err != nil {
84			return Quotation{}, err
85		}
86	
87		// find the weight tier (see the TODO on bracketIndex about tier edges)
88		grams := p.BillableGrams()
89		limits := make([]int, len(tiers))
90		for i := range tiers {
91			limits[i] = tiers[i].UpToGrams
92		}
93		idx := bracketIndex(limits, grams)
94		if idx == len(tiers) {
95			return Quotation{}, fmt.Errorf("%w: %d g billable, %s limit is %d g",
96				ErrTooHeavy, grams, svc, tiers[len(tiers)-1].UpToGrams)
97		}
98		tier := tiers[idx]
99	
100		q := Quotation{Service: svc, Zone: zone, Grams: grams}
101	
102		// base postage for the zone
103		base := applyZoneFactor(tier.Cents, zone)
104		q.Charges = append(q.Charges, Charge{
105			Name:  fmt.Sprintf("Postage (%s, up to %d g, zone %d)", svc, tier.UpToGrams, zone),
106			Cents: base,
107		})
108	
109		// fuel
110		fuel := calcFuel(base)
111		if fuel > 0 {
112			q.Charges = append(q.Charges, Charge{Name: "Fuel surcharge", Cents: fuel})
113		}
114	
115		// residential
116		if r := ResidentialSurcharge(svc, p.Residential); r > 0 {
117			q.Charges = append(q.Charges, Charge{Name: "Residential delivery", Cents: r})
118		}
119	
120		// oversize
121		over, err := OversizeFee(p)
122		if err != nil {
123			return Quotation{}, err
124		}
125		if over > 0 {
126			q.Charges = append(q.Charges, Charge{Name: "Oversize", Cents: over})
127		}
128	
129		// remote area
130		remote := RemoteAreaSurcharge(toPostcode)
131		if remote != 0 {
132			q.Charges = append(q.Charges, Charge{Name: "Remote area", Cents: remote})
133		}
134	
135		// insurance
136		if p.DeclaredValueCents > 0 {
137			ins, err := InsuranceFee(p.DeclaredValueCents)
138			if err != nil {
139				return Quotation{}, err
140			}
141			q.Charges = append(q.Charges, Charge{
142				Name:  "Insurance (declared " + formatCents(p.DeclaredValueCents) + ")",
143				Cents: ins,
144			})
145		}
146	
147		// total
148		var total int64
149		for i := 0; i < len(q.Charges); i++ {
150			total = total + q.Charges[i].Cents
151		}
152		q.TotalCents = total
153		return q, nil
154	}
155	
156	// CheapestService returns the cheaper of the Standard and Express quotes.
157	// Express wins only if it is strictly cheaper.
158	func CheapestService(p Parcel, fromPostcode, toPostcode string) (Quotation, error) {
159		std, err := Quote(p, fromPostcode, toPostcode, Standard)
160		if err != nil {
161			return Quotation{}, err
162		}
163		exp, err := Quote(p, fromPostcode, toPostcode, Express)
164		if err != nil {
165			return std, nil
166		}
167		if exp.TotalCents < std.TotalCents {
168			return exp, nil
169		}
170		return std, nil
171	}
172	
173	// String renders the quotation as a plain-text receipt.
174	func (q Quotation) String() string {
175		var b strings.Builder
176		for _, c := range q.Charges {
177			b.WriteString(fmt.Sprintf("%-40s %10s\n", c.Name, formatCents(c.Cents)))
178		}
179		b.WriteString(fmt.Sprintf("%-40s %10s\n", "Total", formatCents(q.TotalCents)))
180		return b.String()
181	}
182	
183	// RateCard renders the zone-1 price list for a service, one tier per line,
184	// in the format printed on the counter poster.
185	func RateCard(svc Service) string {
186		tiers := standardTiers
187		if svc == Express {
188			tiers = expressTiers
189		}
190		var b strings.Builder
191		b.WriteString(svc.String() + " parcels, zone 1\n")
192		for _, t := range tiers {
193			b.WriteString("up to " + strconv.Itoa(t.UpToGrams) + " g\t" + formatCents(t.Cents) + "\n")
194		}
195		return b.String()
196	}
197	
198	// formatCents renders a non-negative amount of cents as dollars, e.g. 1250 -> "$12.50".
199	func formatCents(c int64) string {
200		return "$" + strconv.FormatInt(c/100, 10) + "." + fmt.Sprintf("%02d", c%100)
201	}
