1	package parcelrate
2	
3	import (
4		"errors"
5		"fmt"
6	)
7	
8	// Parcel describes one package to be shipped. Weights are in grams and
9	// dimensions in whole centimetres.
10	type Parcel struct {
11		WeightGrams        int
12		LengthCm           int
13		WidthCm            int
14		HeightCm           int
15		DeclaredValueCents int64 // 0 means "no insurance requested"
16		Residential        bool  // delivery to a home address rather than a business
17	}
18	
19	var (
20		ErrInvalidParcel = errors.New("parcelrate: invalid parcel")
21		ErrTooHeavy      = errors.New("parcelrate: parcel is too heavy for this service")
22		ErrOversize      = errors.New("parcelrate: parcel is too large to ship")
23		ErrNotInsurable  = errors.New("parcelrate: declared value is above the insurable limit")
24	)
25	
26	// Volumetric weight uses a divisor of 6000 cm3 per kg.
27	const volumetricDivisor = 5000
28	
29	// weightStepGrams is the billing increment: billable weight is always rounded
30	// up to the next multiple of this.
31	const weightStepGrams = 100
32	
33	// Validate reports whether the parcel has usable measurements.
34	func (p Parcel) Validate() error {
35		if p.WeightGrams <= 0 {
36			return fmt.Errorf("%w: weight must be positive, got %d g", ErrInvalidParcel, p.WeightGrams)
37		}
38		if p.LengthCm <= 0 || p.WidthCm <= 0 || p.HeightCm <= 0 {
39			return fmt.Errorf("%w: dimensions must be positive, got %dx%dx%d cm",
40				ErrInvalidParcel, p.LengthCm, p.WidthCm, p.HeightCm)
41		}
42		if p.DeclaredValueCents < 0 {
43			return fmt.Errorf("%w: declared value must not be negative", ErrInvalidParcel)
44		}
45		return nil
46	}
47	
48	// volumetricGrams is the dimensional weight in grams: L*W*H / divisor, in kg.
49	func (p Parcel) volumetricGrams() int {
50		cm3 := p.LengthCm * p.WidthCm * p.HeightCm
51		return cm3 * 1000 / volumetricDivisor
52	}
53	
54	// BillableGrams is the greater of the actual and the volumetric weight,
55	// rounded up to the next weightStepGrams.
56	func (p Parcel) BillableGrams() int {
57		w := p.WeightGrams
58		if v := p.volumetricGrams(); v > w {
59			w = v
60		}
61		return roundUpTo(w, weightStepGrams)
62	}
63	
64	// roundUpTo rounds v up to the next multiple of step (v itself if it already is one).
65	func roundUpTo(v, step int) int {
66		return (v + step - 1) / step * step
67	}
68	
69	// lengthPlusGirthCm returns the longest side plus twice the sum of the other
70	// two sides, which is how carriers measure parcel size.
71	func (p Parcel) lengthPlusGirthCm() int {
72		sides := []int{p.LengthCm, p.WidthCm, p.HeightCm}
73		// sort the three sides, longest first
74		swapped := true
75		for swapped {
76			swapped = false
77			for i := 0; i < len(sides)-1; i++ {
78				if sides[i] < sides[i+1] {
79					tmp := sides[i]
80					sides[i] = sides[i+1]
81					sides[i+1] = tmp
82					swapped = true
83				}
84			}
85		}
86		return sides[0] + 2*(sides[1]+sides[2])
87	}
88	
89	// VolumetricKg returns the dimensional weight in kilograms.
90	//
91	// Deprecated: use Parcel.BillableGrams. Kept for the old label printer.
92	func VolumetricKg(l, w, h int) float64 {
93		return float64(l*w*h) / 6000.0
94	}
