// bracketIndex returns the bracket that v falls into, given the upper limit
// of each bracket in ascending order. It returns len(limits) when v is above
// every bracket. Limits are exclusive: v equal to a limit falls into the next
// bracket up (e.g. insurance's "under $100" band excludes exactly $100).
func bracketIndex(limits []int, v int) int {
	for i, limit := range limits {
		if v < limit {
			return i
		}
	}
	return len(limits)
}

// bracketIndexInclusive is like bracketIndex but treats each limit as
// inclusive ("up to and including"), matching Tier.UpToGrams and the letter
// and zone tables. v equal to a limit falls into that bracket, not the next.
func bracketIndexInclusive(limits []int, v int) int {
	return bracketIndex(limits, v-1)
}

